def greatestLetter(s: str) -> str:
    # Create sets to track all uppercase and lowercase letters in s
    upper = set()
    lower = set()

    for ch in s:
        if 'A' <= ch <= 'Z':
            upper.add(ch)
        elif 'a' <= ch <= 'z':
            lower.add(ch)

    # Check from 'Z' to 'A', return first letter present in both sets
    for i in range(25, -1, -1):
        up = chr(ord('A') + i)
        low = chr(ord('a') + i)
        if up in upper and low in lower:
            return up
    return ""
